/**
 * The order the index renders in: flat and chronological, earliest first, as
 * listed in the handoff. `studies` is already in that order — `id` is the
 * position — so this is a named alias rather than a re-sort.
 */
export const orderedStudies: Study[] = [...studies].sort((a, b) => a.id - b.id);

export const getStudy = (slug: string): Study | undefined =>
  studies.find(s => s.slug === slug);
